// Supabase Edge Function `seal-worker`: runs ONE seal step per invocation
// (docs/supabase-native-architecture.md, CLAUDE.md S.9). `dist/` is
// generated by `pnpm --filter api build:edge`; see apps/api/scripts/build-edge.mjs.
// pg_cron calls it every minute as a backstop; it kicks itself while a job
// has steps left. A failed step backs off in the job row and does not re-kick.
import { ASSET_ROOT, installAssetFs } from '../_shared/asset-fs.ts';
import { serveWorker } from '../_shared/worker-server.ts';
import assets from './dist/assets.mjs';

installAssetFs(assets as Record<string, string>);
(globalThis as { __SEALD_ASSET_DIR?: string }).__SEALD_ASSET_DIR = ASSET_ROOT;

const { createSealWorker } = await import('./dist/edge.mjs');

type Outcome = { kind: string };
type SealWorker = { runOneStep(): Promise<Outcome> };

serveWorker<SealWorker, Outcome>({
  name: 'seal-worker',
  create: createSealWorker as () => SealWorker,
  run: (worker) => worker.runOneStep(),
  // After a finished job another may be queued: check once more.
  more: (outcome) => outcome.kind === 'yielded' || outcome.kind === 'finished',
});
